class Component extends DCLogic {
  componentDidMount(){ const go=()=>window.SWD?SWD.ready(()=>this.init()):setTimeout(go,30); go(); }
  init(){
    const D=SW_DEMO_DATA, CF=SW_DEMO, $=id=>document.getElementById(id), UF=SWD.UFS(), CT=CF.country;
    SWD.page({active:'cresc',lv:'BR',label:'Crescimento'});
    $('vstamp').innerHTML=SWD.stamp('pop'); $('legend').innerHTML=SWD.divLegend(); $('src').innerHTML=SWD.srcLine(['pop','est']);
    const st={sel:SWD.q.get('u')||'RR',hov:null};
    const map=new SW.Map($('map'),{aria:'Crescimento por estado, 2010 a 2022',onHover:u=>{st.hov=u;draw()},onClick:u=>{st.sel=u;draw()}});
    map.update({fill:u=>{const x=D.tx[u]; if(x==null) return {hatch:true}; const k=SWD.cls(x,SWD.GROW.cuts); return {f:`var(--d${k})`,k:k===0||k===5?4:0}}});
    const ord=UF.slice().sort((a,b)=>D.tx[b]-D.tx[a]), mx=Math.max(...UF.map(u=>Math.abs(D.tx[u])));
    const list=$('dv');
    list.onmouseover=e=>{const li=e.target.closest('li[data-uf]'); if(li){st.hov=li.dataset.uf;draw()}}; list.onmouseleave=()=>{st.hov=null;draw()};
    list.onclick=e=>{const li=e.target.closest('li[data-uf]'); if(li){st.sel=li.dataset.uf;draw()}};
    list.onkeydown=e=>{ if(!['ArrowDown','ArrowUp'].includes(e.key)) return; e.preventDefault(); let i=ord.indexOf(st.sel); i=Math.max(0,Math.min(ord.length-1,i+(e.key==='ArrowDown'?1:-1))); st.sel=ord[i]; draw(); list.querySelector(`li[data-uf="${st.sel}"]`).focus(); };
    list.setAttribute('role','listbox');
    const draw=()=>{ const u=st.hov||st.sel, p0=D.pop10[u], p1=D.pop[u], x=D.tx[u], r=ord.indexOf(u)+1, br=D.tx.BR;
      map.mark(st.sel,st.hov);
      $('card').innerHTML=`<div class="card" aria-live="polite">
        <div class="meta">${SWD.region(u)} · ${r}º de ${UF.length} em crescimento</div>
        <div class="row1"><div class="nm">${SWD.name(u)}</div><div class="big">${SWD.sgn(x,2)}<small>% ao ano</small></div></div>
        <div style="margin-top:14px;display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:10px;align-items:center;font-size:14px;color:var(--sub)">
          <span>2010</span><span style="height:2px;background:var(--line2);position:relative"><i style="position:absolute;right:-2px;top:-5px;border-left:7px solid var(--line2);border-top:6px solid transparent;border-bottom:6px solid transparent"></i></span><span>2022</span>
          <b style="color:var(--ink);font-size:20px;font-weight:600">${SWD.mi(p0)}</b><span></span><b style="color:var(--ink);font-size:20px;font-weight:600">${SWD.mi(p1)}</b></div>
        <div class="facts">
          <div class="fact"><span>Diferença de pessoas</span><b>${SWD.sgn(p1-p0,0).replace(/(\d)(?=(\d{3})+$)/g,'$1.')}</b></div>
          <div class="fact"><span>Média de ${CT.name}</span><b>${SWD.sgn(br,2,'% ao ano')}</b></div>
          <div class="fact"><span>Estimativa ${D.estYear} <span class="freq est" style="margin-left:6px">Estimativa</span></span><b>${SWD.mi(D.est[u])}</b></div></div>
        <div style="margin-top:6px">${SWD.stamp('pop')}</div></div>`;
      list.innerHTML=ord.map((v,i)=>{const t=D.tx[v], w=Math.abs(t)/mx*50, k=SWD.cls(t,SWD.GROW.cuts);
        return `<li data-uf="${v}" role="option" tabindex="${v===st.sel?0:-1}" aria-selected="${v===st.sel}" class="${v===st.sel?'on':''} ${v===st.hov?'hv':''}"><span class="n">${i+1}</span><span class="nm">${SWD.name(v)}</span><span class="tr"><i style="${t>=0?`left:50%`:`right:50%`};width:${w}%;background:var(--d${k})"></i></span><span class="v">${SWD.sgn(t,2,'%')}</span></li>`}).join('');
    };
    draw();
  }
  renderVals(){ return {}; }
}
